import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Contacts — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contacts — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/contacts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contacts — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/contacts"}]]},"headers":[],"relativePath":"user-guide/contacts.md","filePath":"user-guide/contacts.md","lastUpdated":1786654474000}'),s={name:"user-guide/contacts.md"};function r(i,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="contacts-—-user-guide" tabindex="-1">Contacts — User Guide <a class="header-anchor" href="#contacts-—-user-guide" aria-label="Permalink to &quot;Contacts — User Guide&quot;">​</a></h1><h2 id="who-can-use-contacts" tabindex="-1">Who can use Contacts <a class="header-anchor" href="#who-can-use-contacts" aria-label="Permalink to &quot;Who can use Contacts&quot;">​</a></h2><p>Your workspace must have the <strong>Contacts</strong> module installed. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code> as needed).</p><p>Without <strong>assign</strong>, you only see contacts assigned to you.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Contacts</strong> from the sidebar.</p><ul><li>Search by name, email, phone, company (legacy string), or job title</li><li>Filter by company, assignee, lifecycle (<strong>On Boarded Clients</strong> / <strong>Off Boarded Clients</strong>), or toggle <strong>My Contacts</strong></li><li>When a contact is linked to a <a href="/user-guide/companies">Company</a>, the table shows the linked company name (falls back to the legacy company string)</li><li>KPI cards summarize total contacts, my contacts, unassigned, on boarded / off boarded clients, with email, and created this week</li><li>The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted contact from the row menu — this trash filter is <strong>not</strong> the same as lifecycle On/Off Boarded</li><li><strong>Delete permanently</strong> (force delete) requires <code>contacts.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New contact</strong></li><li>Enter name (required) and optional email, phone, job title, lifecycle, and assignee</li><li>Optionally pick a <strong>Company</strong> (when the Companies module is installed and you can view companies). Selecting a Company links <code>company_id</code> and syncs the legacy company text to that organization name. Leaving the picker empty keeps any existing free-text company value on edit; clearing a previously linked Company removes the link</li><li>Save</li></ol><p>Edit from the row menu or the detail drawer.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the detail drawer or the create/edit form.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the contact</li><li><strong>Activity</strong> — timeline of create, update, assignment, note, and delete/restore events</li></ul><h2 id="converting-a-lead-to-a-contact" tabindex="-1">Converting a Lead to a Contact <a class="header-anchor" href="#converting-a-lead-to-a-contact" aria-label="Permalink to &quot;Converting a Lead to a Contact&quot;">​</a></h2><p>When your workspace has both <strong>Leads</strong> and <strong>Contacts</strong> installed, converting a Lead (from the Lead detail drawer) creates a linked Contact with lifecycle <strong>On Boarded Clients</strong>. If <strong>Companies</strong> is also installed and the lead has a company name, convert creates or reuses that Company and links it on the Contact. You can optionally create an <strong>Opportunity</strong> in the same step when Opportunities is installed. After conversion, the Lead detail drawer shows <strong>View contact</strong> (and company / opportunity links when applicable).</p>',16)])])}const p=t(s,[["render",r]]);export{m as __pageData,p as default};
